{
  "findings": [
    {
      "check_id": "CKV_AWS_88",
      "title": "EC2 instance should not have public IP.",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "The EC2 instance is placed in a public subnet, which may expose it to the internet. This increases the risk of unauthorized access."
    },
    {
      "check_id": "AVD-AWS-0028",
      "title": "Instance does not require IMDS access to require a token",
      "resource": "aws_instance.web",
      "severity": "HIGH",
      "explanation": "The EC2 instance does not enforce the use of HTTP tokens for the Instance Metadata Service (IMDS), which could allow unauthorized access to sensitive metadata."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"web\" {\n  ami                    = \"${var.ami}\"\n  instance_type          = \"t2.micro\"\n  subnet_id              = \"${aws_subnet.public-subnet.id}\"\n  vpc_security_group_ids = [\"${aws_security_group.sgweb.id}\"]\n\n  associate_public_ip_address = false\n\n  metadata_options {\n    http_tokens = \"required\"\n  }\n}",
  "fix_summary": "Disabled public IP assignment for the EC2 instance to reduce exposure to the internet. Enforced the use of HTTP tokens for the Instance Metadata Service (IMDS) to enhance metadata security."
}
